// ============================================================================
// SPEC-213 L1.5: 205-BYTE BINARY FRAME DECODER & CO-SIMULATION INTERLOCK
// ============================================================================
// Unpacks the exact 205-byte binary frame generated by Python's
// AdversarialCapsuleGateMachine:
//   - WitnessPreCommit  (119 bytes, little-endian <QQ32sfBH32s32s)
//   - WitnessPostCommit ( 86 bytes, little-endian <QQ32sBfB32s)
// Enforces:
//   1. Endianness & bit-alignment verification between Python struct.pack and RTL.
//   2. Cryptographic involution check: post.w_pre_hash == pre.w_pre_hash.
//   3. HPIS Interlock & Landauer thermal audit via fpga_witness_ledger_worm.
//   4. v_gate_out = 0 (0.00 V DC fail-closed) on any mismatch, KILL, or TRAP.
// ============================================================================

`timescale 1ns / 1ps

module fpga_capsule_frame_205b_decoder (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          frame_valid,
    input  wire [951:0]  w_pre_frame_le,   // 119 bytes = 952 bits (byte 0 at [7:0])
    input  wire [687:0]  w_post_frame_le,  //  86 bytes = 688 bits (byte 0 at [7:0])

    output wire [63:0]   pre_seq_id,
    output wire [63:0]   post_seq_id,
    output wire [7:0]    pre_gate_decision,
    output wire [15:0]   pre_reason_code,
    output wire [255:0]  pre_w_pre_hash,
    output wire [255:0]  post_w_pre_hash,
    output wire [7:0]    post_hpis_latch_byte,
    output wire [7:0]    post_final_status,
    output reg           capsule_linkage_ok,
    output reg           v_gate_out_5v,    // 1 = 5.00 V DC (ACTIVE_LOAD), 0 = 0.00 V DC (FAIL-CLOSED)
    output reg  [7:0]    rtl_verdict_code  // 0x01=SIMULATED_EFFECT, 0x03=KILL, 0xEE=INTERLOCK_MISMATCH, 0xFF=TRAP_TAMPER
);

    // ------------------------------------------------------------------------
    // Little-Endian Unpacking of WitnessPreCommit (<QQ32sfBH32s32s, 119 bytes)
    // Byte offsets:
    //   0..7    : uint64 sequence_id
    //   8..15   : uint64 timestamp_ns
    //   16..47  : 32s    candidate_hash
    //   48..51  : float  kernel_drift_val
    //   52      : uint8  gate_decision
    //   53..54  : uint16 reason_code
    //   55..86  : 32s    prev_block_hash
    //   87..118 : 32s    w_pre_hash
    // ------------------------------------------------------------------------
    assign pre_seq_id        = w_pre_frame_le[63:0];
    assign pre_gate_decision = w_pre_frame_le[52*8 +: 8];
    assign pre_reason_code   = w_pre_frame_le[53*8 +: 16];
    assign pre_w_pre_hash    = w_pre_frame_le[87*8 +: 256];

    // ------------------------------------------------------------------------
    // Little-Endian Unpacking of WitnessPostCommit (<QQ32sBfB32s, 86 bytes)
    // Byte offsets:
    //   0..7    : uint64 sequence_id
    //   8..15   : uint64 timestamp_ns
    //   16..47  : 32s    w_pre_hash
    //   48      : uint8  hpis_latch_status
    //   49..52  : float  thermo_exhaust_nJ (IEEE 754 float32)
    //   53      : uint8  final_status
    //   54..85  : 32s    w_post_hash
    // ------------------------------------------------------------------------
    assign post_seq_id          = w_post_frame_le[63:0];
    assign post_w_pre_hash      = w_post_frame_le[16*8 +: 256];
    assign post_hpis_latch_byte = w_post_frame_le[48*8 +: 8];
    wire [31:0] post_exhaust_f32 = w_post_frame_le[49*8 +: 32];
    assign post_final_status    = w_post_frame_le[53*8 +: 8];

    // Positive IEEE-754 float32 check: sign bit [31] == 0 and magnitude [30:0] != 0
    wire exhaust_positive = (post_exhaust_f32[31] == 1'b0) && (post_exhaust_f32[30:0] != 31'd0);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            capsule_linkage_ok <= 1'b0;
            v_gate_out_5v      <= 1'b0; // 0.00 V DC fail-closed on reset
            rtl_verdict_code   <= 8'h03;
        end else if (frame_valid) begin
            // 1. Check cryptographic linkage between W_PRE (119B) and W_POST (86B)
            if (pre_seq_id != post_seq_id || pre_w_pre_hash != post_w_pre_hash) begin
                capsule_linkage_ok <= 1'b0;
                v_gate_out_5v      <= 1'b0; // 0.00 V DC
                rtl_verdict_code   <= 8'hFF; // TRAP_TAMPER (CapsuleLinkage mismatch)
            end
            // 2. Check HPIS Interlock Mismatch (gate_decision == OPEN (0x01), but latch == 0x00)
            else if (pre_gate_decision == 8'h01 && post_hpis_latch_byte == 8'h00) begin
                capsule_linkage_ok <= 1'b1;
                v_gate_out_5v      <= 1'b0; // 0.00 V DC
                rtl_verdict_code   <= 8'hEE; // INTERLOCK_MISMATCH
            end
            // 3. Nominal OPEN + HPIS Engaged + Final Status REALIZED (0x01)
            else if (pre_gate_decision == 8'h01 && post_hpis_latch_byte == 8'h01 && post_final_status == 8'h01) begin
                capsule_linkage_ok <= 1'b1;
                v_gate_out_5v      <= 1'b1; // 5.00 V DC (SIMULATED_EFFECT in L1.5)
                rtl_verdict_code   <= 8'h01; // SIMULATED_EFFECT
            end
            // 4. KILL / HOLD path: must keep v_gate_out_5v = 0 and have positive Landauer exhaust
            else begin
                capsule_linkage_ok <= exhaust_positive;
                v_gate_out_5v      <= 1'b0; // 0.00 V DC
                rtl_verdict_code   <= exhaust_positive ? 8'h03 : 8'hFF;
            end
        end
    end

endmodule
